#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
int N, V;
vector<int> adj[1600];
vector<int> dist[1600]; // all-pair shortest path distances
vector<int> d; // dirt values

int cell_id(int i, int j) { return i * N + j; }

void bfs_all_distances() {
    for (int s = 0; s < V; s++) {
        dist[s].assign(V, INF);
        queue<int> q;
        q.push(s);
        dist[s][s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (dist[s][v] > dist[s][u] + 1) {
                    dist[s][v] = dist[s][u] + 1;
                    q.push(v);
                }
            }
        }
    }
}

// build spanning tree using BFS from (0,0)
void build_tree(vector<int>& parent) {
    parent.assign(V, -1);
    vector<bool> visited(V, false);
    queue<int> q;
    q.push(0);
    visited[0] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                q.push(v);
            }
        }
    }
}

// generate DFS walk on tree
void dfs_walk(int u, int p, const vector<vector<int>>& tree_adj, vector<int>& walk) {
    for (int v : tree_adj[u]) {
        if (v == p) continue;
        walk.push_back(v);
        dfs_walk(v, u, tree_adj, walk);
        walk.push_back(u);
    }
}

vector<int> initial_walk(const vector<int>& parent) {
    vector<vector<int>> tree_adj(V);
    for (int v = 0; v < V; v++) {
        if (parent[v] != -1) {
            int u = parent[v];
            tree_adj[u].push_back(v);
            tree_adj[v].push_back(u);
        }
    }
    vector<int> walk;
    walk.push_back(0);
    dfs_walk(0, -1, tree_adj, walk);
    return walk;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Input
    cin >> N;
    V = N * N;
    vector<string> h(N-1), v(N);
    for (int i = 0; i < N-1; i++) cin >> h[i];
    for (int i = 0; i < N; i++) cin >> v[i];
    d.resize(V);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> d[cell_id(i, j)];
        }
    }

    // Build graph
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int id = cell_id(i, j);
            // down
            if (i+1 < N && h[i][j] == '0') {
                int nid = cell_id(i+1, j);
                adj[id].push_back(nid);
            }
            // up
            if (i-1 >= 0 && h[i-1][j] == '0') {
                int nid = cell_id(i-1, j);
                adj[id].push_back(nid);
            }
            // right
            if (j+1 < N && v[i][j] == '0') {
                int nid = cell_id(i, j+1);
                adj[id].push_back(nid);
            }
            // left
            if (j-1 >= 0 && v[i][j-1] == '0') {
                int nid = cell_id(i, j-1);
                adj[id].push_back(nid);
            }
        }
    }

    // All-pair distances
    bfs_all_distances();

    // Spanning tree
    vector<int> parent;
    build_tree(parent);
    auto walk = initial_walk(parent); // positions after move, including start

    const int MAX_L = 100000;

    // Main optimization loop
    while (false && walk.size() - 1 < MAX_L) {
        int L = (int)walk.size() - 1;
        // Collect visit times for each cell
        vector<vector<int>> times(V);
        for (int t = 1; t <= L; t++) {
            times[walk[t]].push_back(t);
        }

        double best_score = -1e30;
        int best_v = -1, best_u = -1, best_t_mid = -1;

        for (int v = 0; v < V; v++) {
            const auto& tv = times[v];
            if (tv.empty()) continue;
            int k = tv.size();
            for (int i = 0; i < k; i++) {
                int t_prev = tv[i];
                int t_next = (i+1 < k) ? tv[i+1] : tv[0];
                int I;
                if (i+1 < k) {
                    I = t_next - t_prev;
                } else {
                    I = (L - t_prev) + t_next;
                }
                if (I <= 0) continue;

                // midpoint
                int mid_offset = I / 2;
                int t_mid = t_prev + mid_offset;
                if (t_mid > L) t_mid -= L;
                int cell_u = walk[t_mid];
                int d_uv = dist[cell_u][v];
                if (d_uv == INF) continue;

                int T_start = t_mid;
                int T_visit = T_start + d_uv;
                int end_time = (i+1 < k) ? t_next : t_next + L;
                if (T_visit >= end_time) continue;

                int I1 = T_visit - t_prev;
                int I2 = end_time - T_visit;
                long long reduction = (long long)I * I - (long long)I1 * I1 - (long long)I2 * I2;
                if (reduction <= 0) continue;

                double score = (double)d[v] * reduction / (2.0 * d_uv);
                if (score > best_score) {
                    best_score = score;
                    best_v = v;
                    best_u = cell_u;
                    best_t_mid = t_mid;
                }
            }
        }

        if (best_v == -1) break; // no improvement

        // BFS to get shortest path from best_u to best_v
        vector<int> parent_bfs(V, -1);
        queue<int> q;
        q.push(best_u);
        parent_bfs[best_u] = best_u;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == best_v) break;
            for (int nb : adj[u]) {
                if (parent_bfs[nb] == -1) {
                    parent_bfs[nb] = u;
                    q.push(nb);
                }
            }
        }

        // reconstruct path from best_u to best_v (excluding best_u, including best_v)
        vector<int> path_fwd;
        int cur = best_v;
        while (cur != best_u) {
            path_fwd.push_back(cur);
            cur = parent_bfs[cur];
        }
        reverse(path_fwd.begin(), path_fwd.end()); // now order: first neighbor of best_u, ..., best_v

        // build insertion sequence: forward path + reverse path (excluding duplicate v and including best_u at end)
        vector<int> insert_seq;
        for (int x : path_fwd) insert_seq.push_back(x);
        for (int i = (int)path_fwd.size() - 2; i >= 0; i--) {
            insert_seq.push_back(path_fwd[i]);
        }
        insert_seq.push_back(best_u);

        // insert into walk at position best_t_mid
        vector<int> new_walk;
        new_walk.reserve(walk.size() + insert_seq.size());
        for (int i = 0; i <= best_t_mid; i++) {
            new_walk.push_back(walk[i]);
        }
        for (int x : insert_seq) {
            new_walk.push_back(x);
        }
        for (int i = best_t_mid + 1; i < (int)walk.size(); i++) {
            new_walk.push_back(walk[i]);
        }
        walk.swap(new_walk);
    }

    // Convert walk to move string
    string ans;
    for (size_t i = 0; i + 1 < walk.size(); i++) {
        int cur = walk[i];
        int nxt = walk[i+1];
        int ci = cur / N, cj = cur % N;
        int ni = nxt / N, nj = nxt % N;
        if (ni == ci + 1) ans += 'D';
        else if (ni == ci - 1) ans += 'U';
        else if (nj == cj + 1) ans += 'R';
        else if (nj == cj - 1) ans += 'L';
        else {
            // should not happen, but fallback
            ans += '?';
        }
    }
    cout << ans << '\n';

    return 0;
}

